async function listOrders(userId: string) {
  const orders = await db.orders.findMany({ where: { userId } });
  for (const order of orders) {
    order.items = await db.orderItems.findMany({ where: { orderId: order.id } });
  }
  return orders;
}

주문 50건이면 쿼리가 51번 나간다. findMany 를 한 번 더 도는 대신 orderId 를 모아 IN 절로 한 번에 받고 메모리에서 묶으면 2번으로 끝난다.
